input.command:
cd /private/var/folders/kp/vdv61pd97vd0x29b257r8h7h0000gn/T/opencode
for pair in "D fLexgOxsZu0" "J LjhCEhWiKXk" "H 34Na4j8AVgA" "B PIh2xe4jnpk" "E 09R8_2nJtjg" "I k2qgadSvNyU" "G OPf0YbXqDm0" "F CevxZvSJLk8" "C 9bZkp7q19f0" "A AJtDX37az40"; do
  name=${pair%% *}; id=${pair##* }
  curl -s -m 15 -A "Mozilla/5.0" "https://inv.nadeko.net/api/v1/storyboards/$id" -o "sb_$name.json"
done
python3 << 'EOF'
import json, glob
for f in sorted(glob.glob('sb_*.json')):
    try:
        d = json.load(open(f))
        sbs = d.get('storyboards', [])
        best = None
        for s in sbs:
            if s.get('interval') and (best is None or s['interval'] < best['interval']):
                if s['width'] >= 80:
                    best = s
        if best is None and sbs: best = sbs[-1]
        print(f, "levels:", [(s['width'],s['height'],s['interval'],s['count']) for s in sbs])
    except Exception as e:
        print(f, 'ERR', e)
EOF

